    // DefaultPIE reports whether goos/goarch produces a PIE binary when using the
    // "default" buildmode. On Windows this is affected by -race,
    // so force the caller to pass that in to centralize that choice.
    bool DefaultPIE(gocpp::string goos, gocpp::string goarch, bool isRace)
    {
        //Go switch emulation
        {
            auto condition = goos;
            int conditionId = -1;
            if(condition == "android"_s) { conditionId = 0; }
            else if(condition == "ios"_s) { conditionId = 1; }
            else if(condition == "windows"_s) { conditionId = 2; }
            else if(condition == "darwin"_s) { conditionId = 3; }
            switch(conditionId)
            {
                case 0:
                case 1:
                    return true;
                    break;
                case 2:
                    if(isRace)
                    {
                        // PIE is not supported with -race on windows;
                        // see https://go.dev/cl/416174.
                        return false;
                    }
                    return true;
                    break;
                case 3:
                    return true;
                    break;
            }
        }
        return false;
    }

